package vn.edu.hunre.nhom11.carrental.payment.api;import java.math.BigDecimal;import org.springframework.web.bind.annotation.*;import vn.edu.hunre.nhom11.carrental.payment.domain.Payment;import vn.edu.hunre.nhom11.carrental.payment.service.PaymentService;@RestController@RequestMapping("/api/payments")public class PaymentController{private final PaymentService service;public PaymentController(PaymentService s){service=s;}@PostMapping Object pay(@RequestBody Request r){return service.pay(r.bookingId(),r.amount(),r.method());}@GetMapping("/{bookingId}")Object list(@PathVariable Long bookingId){return service.byBooking(bookingId);}record Request(Long bookingId,BigDecimal amount,Payment.Method method){}}

